python3 -c 'import os,json,hashlib,subprocess,xml.etree.ElementTree as ET; from pathlib import Path
root=Path(os.environ["LABVIEW_ENVIRONMENT"])/"actor-framework"
assert subprocess.run(["git","-C",str(root),"rev-parse","HEAD"],capture_output=True,text=True,check=True).stdout.strip()=="371c631c16155d88f02be11a953e4964d7452fd8"
evidence={"schema_version":1,"status":"public-development-only; author extraction, separate independent review pending; no native execution","method":"Hash original bytes, parse XML directly with stdlib ElementTree, retain required literal locations plus a version-property extra and bounded exact original lines; no evaluated reader used.","cases":{}}
for name in ["library-icon-tests","library-specialty"]:
 p=Path("benchmark/cases/dev")/(name+".json"); c=json.loads(p.read_text()); raw=(root/c["artifact"]["path"]).read_bytes(); assert hashlib.sha256(raw).hexdigest()==c["artifact"]["sha256"]
 tree=ET.fromstring(raw); locations={}
 def walk(el,path):
  for key,value in el.attrib.items(): locations[path+"/@"+key]=value
  locations[path+"/text()"] = el.text
  counts={}
  for child in el:
   counts[child.tag]=counts.get(child.tag,0)+1; walk(child,path+"/"+child.tag+"["+str(counts[child.tag])+"]")
 walk(tree,"/Library")
 rows=[]
 for row in c["reference_inventory"]:
  if not row["citations"]: continue
  cite=row["citations"][0]; loc=cite["locator"]["expression"]; value=locations[loc]; assert value==row["atomic_fact"]["value"]
  rows.append({"claim_id":row["claim_id"],"value":value,"citation":cite})
 version_index=next(i for i,el in enumerate(tree.findall("Property"),1) if el.get("Name")=="NI.Lib.Version")
 loc="/Library/Property["+str(version_index)+"]/text()"; cite=dict(rows[0]["citation"]); cite["locator"]={"scheme":"xml-positional-path","expression":loc}
 lines=[{"line":i,"text":line} for i,line in enumerate(raw.decode("utf-8-sig").splitlines(),1) if line.startswith("<Library ") or "<Item " in line or "Name=\"NI.Lib.Version\"" in line or "Name=\"NI.LV.All.SourceOnly\"" in line]
 evidence["cases"][name]={"artifact":c["artifact"],"case_sha256":hashlib.sha256(p.read_bytes()).hexdigest(),"required_literals":rows,"extra_version":{"value":locations[loc],"citation":cite},"original_excerpt_lines":lines}
p=Path("benchmark/challenge-evidence.json"); p.write_text(json.dumps(evidence,indent=2,sort_keys=True)+"\n")
Path(".session/report.md").write_text("Issue #196 repair in progress. Saved fixtures submitted two claims while expecting complete success and stored mutations as prose.\nVerified the two preferred library originals against their pinned SHA256 and commit; preserved bounded literal evidence in [challenge-evidence.json](../benchmark/challenge-evidence.json).\nBoth libraries retain 12 required IDs per dimension, including two unavailable native slots; VI retains three unavailable slots.\nCorrect XML content cannot establish native fidelity; positive controls and omission outcomes must retain unverified native slots under protocol precedence.\nNo scorer, reader, native job or challenge comparison has executed.\n\n## What next\nReplace the saved generator with materialized controls, frozen per-ID outcomes and separate extras/duplicate/contradiction ledgers; generate coverage README and repin preparation evidence.\nThen run the issue verification and no-write drift checks; request separate substantive review. Do not repeat whole XML/inventory output or infer native answers.\n")
print(json.dumps({"evidence":str(p),"bytes":p.stat().st_size,"cases":{k:{"required_literals":len(v["required_literals"]),"excerpt_lines":len(v["original_excerpt_lines"]),"extra":v["extra_version"]["value"]} for k,v in evidence["cases"].items()}},sort_keys=True))'
